window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a69e225317da2683"]={"versions": [{"id": "FIG-a69e225317da2683", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Spezifikationsbox für eine Modellierungsanforderung (Specification Item / Constraint Rule) im Kontext des AUTOSAR Template Modeling Guide. Es handelt sich um eine gerahmte Textbox zur Definition einer normativen Modellierungsrichtlinie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Element: Gerahmte Regelbox mit grau hinterlegtem Kasten\n</li><li>Identifier / Tag: <code>[ATPS-43]</code>\n</li><li>Titel / Regeltext: <code>Constraints MUST be put into the model at the specified locations</code>\n</li><li>Schnittstellen/Beziehungen: Bezieht sich auf das Anlegen und Platzieren von Constraints an Modell-Elementen im Metamodell bzw. in Enterprise Architect.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationselement einer Spezifikationsanforderung; kein dynamischer Sequenzablauf oder Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikationsanforderung (gekennzeichnet durch das Schlüsselwort <code>MUST</code>). Modellierer und Tool-Entwickler müssen Constraints an den exakt dafür vorgegebenen Stellen im Metamodell platzieren.</p>"}, {"id": "FIG-80eb33a2480c7663", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Spezifikationsbox für eine Modellierungsanforderung (Specification Item / Constraint Rule) im Kontext des AUTOSAR Template Modeling Guide. Es handelt sich um eine gerahmte Textbox zur Definition einer normativen Modellierungsrichtlinie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Element: Gerahmte Regelbox mit grau hinterlegtem Kasten; am oberen Bildrand ragt ein Textfragment des umgebenden Absatzes („the context metaclass.“) in die Darstellung\n</li><li>Identifier / Tag: <code>[ATPS-42]</code>\n</li><li>Titel / Regeltext: <code>Constraints MUST be put into the model at the specified locations</code>\n</li><li>Schnittstellen/Beziehungen: Bezieht sich auf das Anlegen und Platzieren von Constraints an Modell-Elementen im Metamodell bzw. in Enterprise Architect.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationselement einer Spezifikationsanforderung; kein dynamischer Sequenzablauf oder Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikationsanforderung (gekennzeichnet durch das Schlüsselwort <code>MUST</code> unter dem Tag <code>[ATPS-42]</code>). Modellierer und Tool-Entwickler müssen Constraints an den exakt dafür vorgegebenen Stellen im Metamodell platzieren.</p>"}, {"id": "FIG-7cc4f7397187a3f1", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Spezifikationsbox für eine Modellierungsanforderung (Specification Item / Constraint Rule) im Kontext des AUTOSAR Template Modeling Guide. Es handelt sich um eine gerahmte Textbox zur Definition einer normativen Modellierungsrichtlinie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Element: Gerahmte Regelbox mit grau hinterlegtem Kasten\n</li><li>Identifier / Tag: <code>[ATPS-42]</code>\n</li><li>Titel / Regeltext: <code>Constraints MUST be put into the model at the specified locations</code>\n</li><li>Schnittstellen/Beziehungen: Bezieht sich auf das Anlegen und Platzieren von Constraints an Modell-Elementen im Metamodell bzw. in Enterprise Architect.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationselement einer Spezifikationsanforderung; kein dynamischer Sequenzablauf oder Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikationsanforderung (gekennzeichnet durch das Schlüsselwort <code>MUST</code> unter dem Tag <code>[ATPS-42]</code>). Modellierer und Tool-Entwickler müssen Constraints an den exakt dafür vorgegebenen Stellen im Metamodell platzieren.</p>"}, {"id": "FIG-eadf358c48edaf9a", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Spezifikationsbox für eine Modellierungsanforderung (Specification Item / Constraint Rule) im Kontext des AUTOSAR Template Modeling Guide. Es handelt sich um eine gerahmte Textbox zur Definition einer normativen Modellierungsrichtlinie.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Element: Gerahmte Regelbox mit grau hinterlegtem Kasten\n</li><li>Identifier / Tag: <code>[ATPS-42]</code>\n</li><li>Titel / Regeltext: <code>Constraints MUST be put into the model at the specified locations</code>\n</li><li>Schnittstellen/Beziehungen: Bezieht sich auf das Anlegen und Platzieren von Constraints an Modell-Elementen im Metamodell bzw. in Enterprise Architect.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Deklarationselement einer Spezifikationsanforderung; kein dynamischer Sequenzablauf oder Zustandsübergang dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikationsanforderung (gekennzeichnet durch das Schlüsselwort <code>MUST</code> unter dem Tag <code>[ATPS-42]</code>). Modellierer und Tool-Entwickler müssen Constraints an den exakt dafür vorgegebenen Stellen im Metamodell platzieren.</p>"}], "trans": [{"from": "FIG-a69e225317da2683", "to": "FIG-80eb33a2480c7663", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Oberhalb der Regelbox ist das Textfragment „the context metaclass.“ aus dem umgebenden Dokumentabsatz sichtbar.\n</li><li>Das Anforderungs-Tag lautet <code>[ATPS-42]</code> statt <code>[ATPS-43]</code>.\n</li></ul>"}, {"from": "FIG-80eb33a2480c7663", "to": "FIG-7cc4f7397187a3f1", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Der Bildausschnitt ist oben beschnitten; das Textfragment „the context metaclass.“ ist nicht mehr im Bild enthalten.\n</li><li>Das Anforderungs-Tag <code>[ATPS-42]</code> und der Regeltext bleiben unverändert.\n</li></ul>"}, {"from": "FIG-7cc4f7397187a3f1", "to": "FIG-eadf358c48edaf9a", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
